insert into posts (user_id, destinations, date, vibes, bio)
values
('dev-user-1', '[{"mode": "focused", "country": "Argentina", "countryCode": "AR", "cities": ["El Calafate", "Ushuaia"]}]'::jsonb, '{"mode": "focused", "startDate": "2026-09-05", "endDate": "2026-09-20"}'::jsonb, ARRAY['Backpacking', 'Adventure']::text[], 'Chasing glaciers and quiet trails. Looking for one or two people to split a rental car and hike the W trek. Early riser, flexible itinerary.'),
('seed-user-2', '[{"mode": "focused", "country": "Portugal", "countryCode": "PT", "cities": ["Lisbon", "Porto"]}]'::jsonb, '{"mode": "flexible", "earliest": "2026-10-01", "latest": "2026-10-20"}'::jsonb, ARRAY['Road Trip', 'Chill']::text[], 'Slow road trip along the coast, good food, better wine. Dates are flexible within this window — happy to shift to match a good travel partner.'),
('seed-user-3', '[{"mode": "focused", "country": "Japan", "countryCode": "JP", "cities": ["Kyoto", "Kanazawa"]}]'::jsonb, '{"mode": "broad", "months": ["2026-11", "2026-12"]}'::jsonb, ARRAY['Culture', 'Chill']::text[], 'First time in Japan, want to take it slow — temples, tea houses, and a lot of photography. Happy to plan together beforehand.'),
('seed-user-4', '[{"mode": "broad", "regions": ["Africa", "Middle East"]}]'::jsonb, '{"mode": "focused", "startDate": "2026-08-18", "endDate": "2026-08-29"}'::jsonb, ARRAY['Luxury', 'Adventure']::text[], 'Open on the exact country — thinking Cape Town, Marrakech, or Dubai. Splitting a nice place and a couple of guided tours with the right partner.'),
('seed-user-5', '[{"mode": "focused", "country": "Iceland", "countryCode": "IS", "cities": ["Reykjav\u00edk", "Grindav\u00edk"]}]'::jsonb, '{"mode": "focused", "startDate": "2027-01-10", "endDate": "2027-01-17"}'::jsonb, ARRAY['Chill', 'Adventure']::text[], 'Chasing the Northern Lights and hunting for the mythical hot dog stand that''s apparently ''world famous''. Bring thermals, low expectations of sunlight, and a high tolerance for puffin merchandise.'),
('seed-user-6', '[{"mode": "focused", "country": "Norway", "countryCode": "NO", "cities": ["Bergen", "Svolv\u00e6r"]}]'::jsonb, '{"mode": "broad", "months": ["2027-07", "2027-08"]}'::jsonb, ARRAY['Adventure', 'Chill']::text[], 'Fjords so dramatic they should have their own reality show. Looking for a partner who won''t complain when I stop every 200 meters to photograph a sheep on a cliff.'),
('seed-user-7', '[{"mode": "focused", "country": "New Zealand", "countryCode": "NZ", "cities": ["Queenstown", "Wellington"]}]'::jsonb, '{"mode": "flexible", "earliest": "2027-02-01", "latest": "2027-03-15"}'::jsonb, ARRAY['Adventure', 'Backpacking']::text[], 'Will jump off a bridge attached to a rubber band for content. Certified hobbit-hole enthusiast. Looking for someone who screams at the appropriate volume on a bungee.'),
('seed-user-8', '[{"mode": "focused", "country": "Costa Rica", "countryCode": "CR", "cities": ["Tilar\u00e1n", "Liberia"]}]'::jsonb, '{"mode": "focused", "startDate": "2026-12-05", "endDate": "2026-12-15"}'::jsonb, ARRAY['Chill', 'Backpacking']::text[], 'Pura vida energy only. My spirit animal is a sloth and I intend to match its pace exactly. Looking for someone who understands that ''hurry'' is not in the itinerary.'),
('seed-user-9', '[{"mode": "focused", "country": "Vietnam", "countryCode": "VN", "cities": ["Hanoi", "H\u1ea1 Long", "H\u1ed9i An"]}]'::jsonb, '{"mode": "broad", "months": ["2026-08", "2026-09", "2026-10", "2026-11", "2026-12", "2027-01", "2027-04", "2027-05"]}'::jsonb, ARRAY['Backpacking', 'Culture']::text[], 'Extremely flexible human being with an extremely inflexible love of banh mi. Will reroute the entire trip for a good bowl of pho. Motorbike rental optional, motion sickness pills mandatory.'),
('seed-user-10', '[{"mode": "focused", "country": "Greece", "countryCode": "GR", "cities": ["Fir\u00e1", "Athens"]}]'::jsonb, '{"mode": "focused", "startDate": "2026-09-12", "endDate": "2026-09-22"}'::jsonb, ARRAY['Luxury', 'Chill']::text[], 'Here for the sunsets, the feta, and absolutely nothing that requires waking up before 10am. Bring sunglasses big enough to hide the fact that I have no plan beyond ''more olives.'''),
('seed-user-11', '[{"mode": "focused", "country": "Nepal", "countryCode": "NP", "cities": ["Kathmandu", "Namche Bazar"]}]'::jsonb, '{"mode": "flexible", "earliest": "2026-10-05", "latest": "2026-11-05"}'::jsonb, ARRAY['Adventure', 'Backpacking']::text[], 'Looking for a trekking partner who won''t cry (much) at altitude. I will absolutely befriend every yak we pass and give them names. Snacks are non-negotiable.'),
('seed-user-12', '[{"mode": "focused", "country": "Croatia", "countryCode": "HR", "cities": ["Grad Dubrovnik", "Split"]}]'::jsonb, '{"mode": "broad", "months": ["2027-06", "2027-07", "2027-08"]}'::jsonb, ARRAY['Chill', 'Culture']::text[], 'Game of Thrones cosplay strongly encouraged but not required. Mostly here to swim, eat too much seafood, and pretend I understand the walls'' historical significance.'),
('seed-user-13', '[{"mode": "focused", "country": "South Korea", "countryCode": "KR", "cities": ["Seoul", "Busan"]}]'::jsonb, '{"mode": "focused", "startDate": "2027-03-20", "endDate": "2027-03-30"}'::jsonb, ARRAY['Culture', 'Chill']::text[], 'Will plan the entire trip around convenience store snacks and one (1) K-drama filming location. Karaoke stamina required, singing talent not required at all.'),
('seed-user-14', '[{"mode": "focused", "country": "Ireland", "countryCode": "IE", "cities": ["Dublin", "Ennis"]}]'::jsonb, '{"mode": "flexible", "earliest": "2026-09-01", "latest": "2026-09-25"}'::jsonb, ARRAY['Road Trip', 'Chill']::text[], 'Renting a car and driving on the correct side of the road (theirs, not mine). Itinerary is 70% pubs, 20% castles, 10% apologizing to sheep for blocking the road.'),
('seed-user-15', '[{"mode": "focused", "country": "United Kingdom", "countryCode": "GB", "cities": ["Highland", "Portree"]}]'::jsonb, '{"mode": "broad", "months": ["2027-05", "2027-09"]}'::jsonb, ARRAY['Adventure', 'Chill']::text[], 'Seeking a fellow cryptid enthusiast for a very serious, very scientific Loch Ness monster stakeout. Waterproof everything. Bagpipe tolerance a plus but not essential.'),
('seed-user-16', '[{"mode": "focused", "country": "Peru", "countryCode": "PE", "cities": ["Cusco", "Ollantaytambo"]}]'::jsonb, '{"mode": "focused", "startDate": "2026-11-02", "endDate": "2026-11-12"}'::jsonb, ARRAY['Backpacking', 'Adventure', 'Culture']::text[], 'Training regimen for the Inca Trail: climbing exactly zero stairs beforehand and hoping for the best. Alpaca photography is mandatory, altitude complaints are welcome but ignored.'),
('seed-user-17', '[{"mode": "focused", "country": "Philippines", "countryCode": "PH", "cities": ["Puerto Princesa", "Dapa"]}]'::jsonb, '{"mode": "flexible", "earliest": "2027-01-05", "latest": "2027-01-25"}'::jsonb, ARRAY['Chill', 'Backpacking']::text[], 'Island hopping until my phone runs out of storage from lagoon photos that all look identical. Will trade coconut-carrying duties for someone else''s sunscreen.'),
('seed-user-18', '[{"mode": "focused", "country": "Colombia", "countryCode": "CO", "cities": ["Medell\u00edn", "Cartagena de Indias"]}]'::jsonb, '{"mode": "focused", "startDate": "2026-10-08", "endDate": "2026-10-18"}'::jsonb, ARRAY['Culture', 'Road Trip']::text[], 'Salsa lessons booked, two left feet not disclosed to the instructor. Here for the coffee, the color, and confusing every street vendor with my questionable Spanish.'),
('seed-user-19', '[{"mode": "broad", "regions": ["Europe", "Middle East"]}]'::jsonb, '{"mode": "broad", "months": ["2027-03"]}'::jsonb, ARRAY['Luxury', 'Culture']::text[], 'Playing passport roulette — could end up in a rooftop bar in Athens or a souk in Dubai, honestly thrilled either way. Looking for someone equally unbothered by uncertainty and overpacking.'),
('seed-user-20', '[{"mode": "focused", "country": "France", "countryCode": "FR", "cities": ["Paris", "Chamonix-Mont-Blanc"]}, {"mode": "focused", "country": "Switzerland", "countryCode": "CH", "cities": ["Zermatt", "Interlaken"]}]'::jsonb, '{"mode": "focused", "startDate": "2026-09-14", "endDate": "2026-09-28"}'::jsonb, ARRAY['Adventure', 'Road Trip']::text[], 'Alpine loop through the French and Swiss Alps — glacier hikes by day, fondue by night. Looking for a co-driver who''s fine with switchbacks and cable cars.'),
('seed-user-21', '[{"mode": "focused", "country": "India", "countryCode": "IN", "cities": ["Jaipur", "Udaipur", "Jodhpur"]}]'::jsonb, '{"mode": "broad", "months": ["2026-12", "2027-01", "2027-02"]}'::jsonb, ARRAY['Culture', 'Backpacking']::text[], 'Rajasthan''s forts, markets, and street food circuit. Camera-heavy, haggling-friendly, always down for one more chai stop.'),
('seed-user-22', '[{"mode": "broad", "regions": ["South America"]}]'::jsonb, '{"mode": "flexible", "earliest": "2027-02-10", "latest": "2027-04-01"}'::jsonb, ARRAY['Backpacking', 'Adventure']::text[], 'Open-ended South America loop — Patagonia glaciers to Andean altiplano, exact route negotiable. Traveling light, moving slow, saying yes to detours.'),
('seed-user-23', '[{"mode": "focused", "country": "Thailand", "countryCode": "TH", "cities": ["Bangkok", "Chiang Mai", "Ko Lanta"]}]'::jsonb, '{"mode": "focused", "startDate": "2027-01-15", "endDate": "2027-01-29"}'::jsonb, ARRAY['Chill', 'Culture']::text[], 'Temple mornings, night market dinners, a few slow beach days at the end. Vegetarian-friendly itinerary a plus.'),
('seed-user-24', '[{"mode": "broad", "regions": ["Europe"]}]'::jsonb, '{"mode": "broad", "months": ["2027-06", "2027-07"]}'::jsonb, ARRAY['Road Trip', 'Culture']::text[], 'Slow motorhome loop through the Alps region — no fixed route, just good roads, mountain villages, and cheese. Flexible on exact countries.'),
('seed-user-25', '[{"mode": "focused", "country": "Australia", "countryCode": "AU", "cities": ["Sydney", "Byron Bay", "Cairns"]}]'::jsonb, '{"mode": "flexible", "earliest": "2027-04-01", "latest": "2027-06-15"}'::jsonb, ARRAY['Backpacking', 'Adventure']::text[], 'East coast hostel-hopping, surf lessons, and the Great Barrier Reef before it''s gone. Working holiday visa in hand, budget tight, energy high.'),
('seed-user-26', '[{"mode": "focused", "country": "Morocco", "countryCode": "MA", "cities": ["Marrakech", "Chefchaouene", "Errachidia"]}]'::jsonb, '{"mode": "focused", "startDate": "2026-10-20", "endDate": "2026-10-30"}'::jsonb, ARRAY['Culture', 'Adventure']::text[], 'Medinas, blue streets, and a night camping under the stars in the Sahara. Looking for someone who can haggle better than me.'),
('seed-user-27', '[{"mode": "focused", "country": "Mexico", "countryCode": "MX", "cities": ["Oaxaca", "Ciudad de M\u00e9xico", "Tulum"]}]'::jsonb, '{"mode": "broad", "months": ["2026-11", "2026-12"]}'::jsonb, ARRAY['Culture', 'Chill']::text[], 'Mezcal tastings in Oaxaca, murals and markets in CDMX, cenote days in Tulum. Foodie itinerary, open to reshuffling stops.'),
('seed-user-28', '[{"mode": "focused", "country": "Canada", "countryCode": "CA", "cities": ["Banff", "Jasper Park Lodge", "Vancouver"]}]'::jsonb, '{"mode": "focused", "startDate": "2027-07-05", "endDate": "2027-07-19"}'::jsonb, ARRAY['Adventure', 'Road Trip']::text[], 'Rockies road trip — turquoise lakes, hiking boots on daily, tent most nights. Bear spray provided, snoring not guaranteed to be minimal.'),
('seed-user-29', '[{"mode": "focused", "country": "Brazil", "countryCode": "BR", "cities": ["Rio de Janeiro", "Ilha Grande"]}]'::jsonb, '{"mode": "flexible", "earliest": "2027-01-02", "latest": "2027-02-10"}'::jsonb, ARRAY['Chill', 'Adventure']::text[], 'Beach days, samba nights, and a boat trip out to Ilha Grande. Carnival-adjacent timing, up for spontaneity.'),
('seed-user-30', '[{"mode": "broad", "regions": ["Africa"]}]'::jsonb, '{"mode": "broad", "months": ["2027-06", "2027-07", "2027-08"]}'::jsonb, ARRAY['Adventure', 'Luxury']::text[], 'Safari-focused, exact country still open — leaning Kenya or Tanzania depending on migration timing. Splitting a guide and a good camera lens.'),
('seed-user-31', '[{"mode": "focused", "country": "Italy", "countryCode": "IT", "cities": ["Rome", "Florence", "Venice"]}, {"mode": "focused", "country": "Slovenia", "countryCode": "SI", "cities": ["Ljubljana", "Bled"]}]'::jsonb, '{"mode": "focused", "startDate": "2026-09-08", "endDate": "2026-09-23"}'::jsonb, ARRAY['Culture', 'Chill']::text[], 'Classic Italy hits, then a quiet detour into Slovenia before flying home. Museums in the morning, wine in the afternoon.'),
('seed-user-32', '[{"mode": "focused", "country": "Indonesia", "countryCode": "ID", "cities": ["Ubud", "Kuta", "Klungkung"]}]'::jsonb, '{"mode": "broad", "months": ["2027-03", "2027-04"]}'::jsonb, ARRAY['Chill', 'Backpacking']::text[], 'Month in Bali — yoga in the mornings, scooter days exploring Nusa Penida, digital nomad cafes in between. Looking for a low-drama roommate/travel partner.'),
('seed-user-33', '[{"mode": "focused", "country": "Germany", "countryCode": "DE", "cities": ["Berlin", "Munich"]}]'::jsonb, '{"mode": "flexible", "earliest": "2026-12-10", "latest": "2027-01-05"}'::jsonb, ARRAY['Culture', 'Chill']::text[], 'Christmas markets, mulled wine, and a couple of museum days. Timing flexible around the holidays — happy to sync with a partner''s schedule.'),
('seed-user-34', '[{"mode": "focused", "country": "South Africa", "countryCode": "ZA", "cities": ["Cape Town", "Stellenbosch", "Hermanus"]}]'::jsonb, '{"mode": "focused", "startDate": "2026-11-14", "endDate": "2026-11-24"}'::jsonb, ARRAY['Luxury', 'Adventure']::text[], 'Table Mountain, whale watching in Hermanus, and way too many wine farm stops in between. Rental car and good playlist required.'),
('seed-user-35', '[{"mode": "focused", "country": "Turkey", "countryCode": "TR", "cities": ["Fatih", "G\u00f6reme", "Antalya"]}]'::jsonb, '{"mode": "broad", "months": ["2026-09", "2026-10"]}'::jsonb, ARRAY['Culture', 'Adventure']::text[], 'Hot air balloons at sunrise in Cappadocia, bazaars in Istanbul, coastline in Antalya to close it out. Open to reordering the route.'),
('seed-user-36', '[{"mode": "broad", "regions": ["East Asia/SE Asia"]}]'::jsonb, '{"mode": "flexible", "earliest": "2026-10-15", "latest": "2026-12-01"}'::jsonb, ARRAY['Backpacking', 'Culture']::text[], 'First big SE Asia loop, exact countries TBD based on visas and weather — thinking Vietnam, Laos, Cambodia. Slow travel, overland where possible.'),
('seed-user-37', '[{"mode": "focused", "country": "Chile", "countryCode": "CL", "cities": ["Santiago", "Torres del Paine"]}]'::jsonb, '{"mode": "focused", "startDate": "2027-02-15", "endDate": "2027-02-28"}'::jsonb, ARRAY['Adventure', 'Backpacking']::text[], 'W trek in Torres del Paine, then a few easy days in Santiago wine country to recover. Camping gear split three ways if we can find a third.'),
('seed-user-38', '[{"mode": "focused", "country": "Spain", "countryCode": "ES", "cities": ["Barcelona", "Sevilla"]}, {"mode": "focused", "country": "Morocco", "countryCode": "MA", "cities": ["Tangier"]}]'::jsonb, '{"mode": "flexible", "earliest": "2026-09-20", "latest": "2026-10-25"}'::jsonb, ARRAY['Culture', 'Road Trip']::text[], 'Andalusia road trip that ends with a ferry hop across the strait into Tangier for a few days. Tapas budget non-negotiable.'),
('seed-user-39', '[{"mode": "broad", "regions": ["North America"]}]'::jsonb, '{"mode": "broad", "months": ["2027-09", "2027-10"]}'::jsonb, ARRAY['Road Trip', 'Adventure']::text[], 'Big fall national parks road trip — exact states still open, chasing good foliage and open campsites. Van life or bust.')
